    }
    else if(command.startsWith('reconciliation-'))await runReconciliationCLI(command.slice('reconciliation-'.length),options,w,{readText,output});
    else if(command.startsWith('flow-')){
      const op=command.slice(5);
      if(['comparison-report','comparison-bundle','comparison-csv'].includes(op)){
        if(!input)throw Error('Supply the complete original comparison selection with --file.');
        if(op==='comparison-bundle'&&!options.output)throw Error('A complete comparison ZIP requires --output FILE.zip.');
        const product=flowComparisonOperation(w,'POST',[op],JSON.parse(input.text));
        if(options.output){
          const body=op==='comparison-bundle'?Buffer.from(product.base64,'base64'):Buffer.from(product.content);
          await publishExactFile(options.output,body);
          process.stdout.write(JSON.stringify({output:options.output,name:product.name,bytes:body.length,sha256:hash(body),comparison_id:product.comparison_id,before_id:product.before_id,after_id:product.after_id})+'\n');
        }else await output(product.content);
      }
      else if(op==='bundle'||op==='load-bundle'){
        if(!options.output)throw Error('A complete ZIP requires --output FILE.zip');
        const bundle=op==='bundle'?flowStudyBundle(w,options.id):flowLoadBundle(w,options.id);
        await publishExactFile(options.output,Buffer.from(bundle.base64,'base64'));
        process.stdout.write(JSON.stringify({output:options.output,name:bundle.name,bytes:bundle.bytes,sha256:bundle.sha256})+'\n');
      }
      else if(op==='report')await output(renderFlowStudy(readFlowStudy(w,options.id)));
      else if(op==='load-report')await output(renderFlowLoads(readFlowLoadResult(w,options.id)));
      else if(op==='load-read')await output(readFlowLoadResult(w,options.id));
      else if(['load-daily','load-periods','load-context','load-annual'].includes(op))await output(flowLoadCSV(readFlowLoadResult(w,options.id),op.slice(5)));
      else if(op.startsWith('load-'))await output(await flowLoadOperation(w,op==='load-catalogue'?'GET':'POST',[op],input?JSON.parse(input.text):{}));
      else if(op==='read')await output(readFlowStudy(w,options.id));
      else if(['daily','periods','samples'].includes(op))await output(flowCSV(readFlowStudy(w,options.id),op));
      else await output(await flowOperation(w,op==='catalogue'?'GET':'POST',[op],input?JSON.parse(input.text):{}));
    }
    else if(command==='preview')await output(w.preview(input));
    else if(command==='import')await output(w.import(input));
    else if(command==='fetch')await output(w.import(await fetchProvider({kind:options.kind||'wqp',stationId:options.station,huc:options.huc,from:options.from,to:options.to,characteristic:options.characteristic,label:options.label})));
    else if(command==='collection-preview'||command==='collection-receive'){const manifest=JSON.parse(await readText(options.manifest));const received=collectionFromFiles(manifest,options['source-root']||path.dirname(path.resolve(options.manifest)));await output(command==='collection-preview'?previewCollection(w,received):receiveCollection(w,received));}
    else if(command==='collections')await output(listCollections(w));
    else if(command==='collection-publish')await output(publishCollection(w,options.id));
    else if(command==='summary')await output(w.summary());
    else if(command==='records')await output(w.records({stationId:options.station,parameter:options.parameter,limit:options.limit,offset:options.offset}));
    else if(command==='export')await output(w.exportRecords());
    else if(command==='calibration'){const x=calibrationExport(w,{stationId:options.station,parameter:options.parameter});await output(options.format==='csv'?calibrationCSV(x):x);}
    else if(command==='portable')await output(w.portable());
    else if(command==='receive')await output(w.receive(JSON.parse(input.text)));
    else if(command==='map'){const reaches=JSON.parse(await fs.readFile(path.join(directory,'reaches.json'),'utf8'));await output(w.mapping(options.station,{reachId:options.reach,reviewer:options.reviewer,reason:options.reason},reaches.map(x=>x.id)));}
    else if(command==='review')await output(w.review(options.id,{state:options.state,reviewer:options.reviewer,reason:options.reason,selectVersion:options['select-version']==='true'}));
    else if(command==='loads')await output(pairedLoads(w,{stationId:options.station,flowStationId:options['flow-station'],parameter:options.parameter,rationale:options.reason,from:options.from,to:options.to}));
    else throw new Error('Unknown command: '+command);
  }finally{w.close();}
}

import {mountSediment} from './sediment.mjs';
import {mountObservationEditions} from './observation_editions.mjs';
import {mountSourceHandback} from './source_handback.mjs';
import {mountGuidedIntake} from './measured_intake.mjs';
import {describeResult,renderResult,resultHTML,resultCSV,renderSourceInspection,reasonText,measurementValue,renderObservationContext} from './measured_results.mjs';
import {mountFlowEditions} from './flow_editions.mjs';
import {mountBenchmarks} from './benchmarks.mjs';
import {mountSourceReconciliation} from './source_reconciliation.mjs';
/** Framework-independent measured-data workflow, mounted in the native operator. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=(name,input)=>`<label>${name}${input}</label>`;
const option=(value,text,selected='')=>`<option value="${esc(value)}"${value===selected?' selected':''}>${esc(text)}</option>`;
const num=value=>value===null||value===undefined?'—':Number(value).toLocaleString(undefined,{maximumSignificantDigits:8});
const readText=async file=>new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());
const stamp=value=>value?new Date(value).toLocaleString():'—';
export function mountMeasurements(host,{base='/api/measurement-workspace',css='/measurements/workspace.css',transport,initialBenchmarkState=null,initialSedimentState=null,sedimentScope='',onSedimentState=()=>{},sourceHandbackState=null,onSourceHandbackState=()=>{},sourceHandbackCss='/measurements/source_handback.css',observationEditionState=null,onObservationEditionState=()=>{},observationEditionCss=null}={}){
  if(!(host instanceof Element))throw new TypeError('An existing DOM element is required');
  const style=document.createElement('link');style.rel='stylesheet';style.href=css;document.head.append(style);
  const controller=new AbortController();let dead=false,source=null,preview=null,summary=null,page=null,tab='sources',offset=0,filters={},selected=null,busy=false,handbackDesk=null,handbackSnapshot=sourceHandbackState,handbackGeneration=0,flowDesk=null,flowSnapshot=null,benchmarkDesk=null,benchmarkSnapshot=initialBenchmarkState,benchmarkLeavePrepared=false,sedimentDesk=null,sedimentSnapshot=initialSedimentState,sedimentLeavePrepared=false,sourceReviewDesk=null,sourceReviewSnapshot=null,observationEditionDesk=null,observationEditionSnapshot=observationEditionState,result=null,resultId='',resultOffsets={},history=null,historyOffset=0;
  host.classList.add('mw');
  host.innerHTML=`<header class="mw-head"><div><div class="mw-eyebrow">UPPER SAVANNAH / OPERATOR WORKSPACE</div><h1>Measured data</h1><p>Receive originals. Inspect measurements. Assign native reaches. Export reviewed inputs.</p></div><button data-action="refresh">Refresh</button></header><div class="mw-stats" aria-label="Workspace totals"></div><nav class="mw-nav" aria-label="Measured data"><button data-tab="sources">Receive sources</button><button data-tab="records">Measurements</button><button data-tab="stations">Station assignments</button><button data-tab="flow">Daily flow</button><button data-tab="benchmarks">Benchmarks</button><button data-tab="sediment">Sediment models</button><button data-tab="source-review">Source versions</button><button data-tab="observation-editions">Observation editions</button><button data-tab="exports">Exports &amp; handover</button><button data-tab="handback">Source returns</button><button data-tab="results">Saved results</button><button data-tab="archive">Source archive</button></nav><div class="mw-status" role="status" aria-live="polite">Opening saved workspace…</div><section class="mw-content"></section>`;
  const area=host.querySelector('.mw-content'),status=host.querySelector('.mw-status');
  function message(text,error=false){status.textContent=text;status.dataset.error=String(error);}
  async function request(path='',method='GET',value){return transport?await transport(path,method,value):await fetch(base+path,{method,credentials:'same-origin',signal:controller.signal,headers:value===undefined?{}:{'Content-Type':'application/json'},body:value===undefined?undefined:JSON.stringify(value)});}
  async function api(path='',method='GET',value){
    if(value!==undefined&&new TextEncoder().encode(JSON.stringify(value)).byteLength>128*1024*1024)throw new Error('The complete JSON request exceeds the native 128 MiB route. Original file and unfinished inputs remain in the guided preparation; download them or use the existing large-file intake.');
    const result=await request(path,method,value);
    const text=await result.text();if(dead){const error=new Error('Measurement view was closed');error.name='AbortError';throw error;}let data;try{data=JSON.parse(text);}catch{throw new Error('The operator returned an unexpected response. Saved sources remain available.');}
    if(!result.ok)throw new Error(data.error||`HTTP ${result.status}`);return data;
  }
  async function task(operation){if(busy)return;busy=true;host.setAttribute('aria-busy','true');try{await operation();}catch(error){if(error.name!=='AbortError')message(error.message,true);}finally{busy=false;if(!dead)host.setAttribute('aria-busy','false');}}
  const intake=mountGuidedIntake({api,onImported:()=>refresh()});
  function stationOptions(value=''){return option('','Select an imported station',value)+(summary?.stations||[]).map(s=>option(s.id,`${s.id} · ${s.name}`,value)).join('');}
  function statBar(){host.querySelector('.mw-stats').innerHTML=[['Measurements',summary.recordCount],['Stations',summary.stations.length],['Original sources',summary.imports.length],['Saved exports',summary.exportCount],['Revision',summary.revision]].map(([k,v])=>`<div><strong>${num(v)}</strong><span>${esc(k)}</span></div>`).join('');}
  async function refresh(){await stopBenchmarks();await stopSediment();summary=await api();if(dead)return;statBar();if(tab==='records')await loadRecords();else if(tab==='results')await loadHistory();else render();message(`Workspace revision ${summary.revision} loaded. Originals and review history are retained locally.`);}
  function stopHandback(){handbackGeneration++;if(handbackDesk){handbackSnapshot=handbackDesk.snapshot();onSourceHandbackState(handbackSnapshot);handbackDesk.destroy();handbackDesk=null;}}
  function renderHandback(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);const token=++handbackGeneration;
    handbackDesk=mountSourceHandback(node,{request,css:sourceHandbackCss,initialState:handbackSnapshot,
      onStateChange:value=>{if(!dead&&token===handbackGeneration){handbackSnapshot=value;onSourceHandbackState(value);}},
      refresh:async()=>{const value=await api();if(dead||token!==handbackGeneration)return;summary=value;statBar();}});
  }
  async function stopBenchmarks(){if(benchmarkDesk){await benchmarkDesk.prepareLeave();benchmarkSnapshot=benchmarkDesk.snapshot();benchmarkDesk.destroy();benchmarkDesk=null;}}
  function renderBenchmarks(){area.replaceChildren();const node=document.createElement('div');area.append(node);benchmarkDesk=mountBenchmarks(node,{request,initialState:benchmarkSnapshot,onRevision:revision=>{if(summary){summary.revision=revision;statBar();}}});}
  async function stopSediment(){if(sedimentDesk){await sedimentDesk.prepareLeave();sedimentSnapshot=sedimentDesk.snapshot();onSedimentState(sedimentSnapshot);sedimentDesk.destroy();sedimentDesk=null;}}
  function renderSediment(){area.replaceChildren();const node=document.createElement('div');area.append(node);sedimentDesk=mountSediment(node,{request,initialState:sedimentSnapshot,scope:sedimentScope,onStateChange:value=>{sedimentSnapshot=value;onSedimentState(value);},onRevision:revision=>{if(summary){summary.revision=revision;statBar();}}});}
  function stopFlow(){if(flowDesk){flowSnapshot=flowDesk.snapshot();flowDesk.destroy();flowDesk=null;}}
  function renderFlow(){area.replaceChildren();const node=document.createElement('div');area.append(node);flowDesk=mountFlowEditions(node,{api:(path,{method='GET',value}={})=>api(path,method,value),request,initialState:flowSnapshot});}
  function rememberObservationEdition(value){observationEditionSnapshot=value;onObservationEditionState(value);}
  function stopObservationEdition(){if(observationEditionDesk){rememberObservationEdition(observationEditionDesk.snapshot());observationEditionDesk.destroy();observationEditionDesk=null;}}
  function renderObservationEdition(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);
    observationEditionDesk=mountObservationEditions(node,{
      api,request,css:observationEditionCss||css.replace(/[^/]*$/,'observation_editions.css'),initialState:observationEditionSnapshot||{},
      onStateChange:rememberObservationEdition,
      onChanged:({revision})=>{if(!dead&&summary){summary.revision=revision;statBar();}},
      openRecord:id=>task(async()=>{stopObservationEdition();tab='records';selected=null;await loadRecords();if(!dead)await inspect(id);}),
      openExports:()=>task(async()=>{stopObservationEdition();tab='exports';selected=null;render();})
    });
  }
  function stopSourceReview(){if(sourceReviewDesk){sourceReviewSnapshot=sourceReviewDesk.snapshot();sourceReviewDesk.destroy();sourceReviewDesk=null;}}
  function renderSourceReview(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);
    sourceReviewDesk=mountSourceReconciliation(node,{
      request,css:css.replace(/[^/]*$/,'source_reconciliation.css'),initialState:sourceReviewSnapshot||{},
      onStateChange:value=>{sourceReviewSnapshot=value;},
      onChanged:({revision})=>{if(!dead&&summary){summary.revision=revision;statBar();}},
      openRecord:id=>task(async()=>{stopSourceReview();tab='records';selected=null;await loadRecords();if(!dead)await inspect(id);}),
      openExports:()=>task(async()=>{stopSourceReview();tab='exports';selected=null;render();})
    });
  }
  function render(){stopHandback();stopFlow();stopSourceReview();stopObservationEdition();if(!summary)return;for(const b of host.querySelectorAll('[data-tab]'))b.setAttribute('aria-current',String(b.dataset.tab===tab));({sources:renderSources,records:renderRecords,stations:renderStations,handback:renderHandback,flow:renderFlow,benchmarks:renderBenchmarks,sediment:renderSediment,'source-review':renderSourceReview,'observation-editions':renderObservationEdition,exports:renderExports,results:renderResults,archive:renderArchive})[tab]();}
  function renderSources(){area.innerHTML=`<div class="mw-grid"><div data-guided-intake></div><section class="mw-panel"><h2>Retrieve public observations</h2><p>WQX 3.0 chemistry and stations; USGS OGC daily mean discharge. The complete query and original response pages are retained.</p><form id="mw-provider">${label('Dataset',`<select name="kind">${option('wqp','WQX 3.0 chemistry')}${option('stations','WQX 3.0 stations')}${option('usgs-daily','USGS daily discharge')}</select>`)}${label('Station identifier','<input name="stationId" placeholder="USGS-… or the exact agency station ID">')}${label('Or an eight-digit HUC','<input name="huc" inputmode="numeric" maxlength="8" placeholder="Exact source watershed identifier">')}<div class="mw-two">${label('From','<input name="from" type="date" required>')}${label('Through','<input name="to" type="date" required>')}</div>${label('Characteristic, optional','<input name="characteristic" placeholder="Exact WQP characteristic name">')}<div class="mw-buttons"><button type="submit">Retrieve &amp; inspect</button><button type="button" data-action="query">Show complete query</button></div></form><div id="mw-query"></div></section></div><section class="mw-preview" aria-label="Source inspection"></section>`;area.querySelector('[data-guided-intake]').append(intake.element);renderPreview();}
  function renderPreview(){const box=area.querySelector('.mw-preview');if(!box)return;if(!preview){box.innerHTML='<p class="mw-muted">Choose a source above. Inspection does not change the workspace.</p>';return;}
    const p=preview;box.innerHTML=`<div class="mw-panel"><div class="mw-panel-head"><h2>Source inspection</h2><button data-action="commit"${!p.rows?' disabled':''}>Import complete source</button></div><p><strong>${num(p.rows)}</strong> accepted rows · <strong>${num(p.rejectedCount)}</strong> rejected rows · ${num(p.stationCount)} stations · ${num(p.censored)} censored results.</p><p>Showing ${num(p.previewCount)} representative source rows below. The import retains the entire original and every rejection.</p><dl><dt>Source</dt><dd>${esc(source.label)}</dd><dt>SHA-256</dt><dd class="mw-mono">${esc(p.contentSha)}</dd></dl>${recordTable(p.sample,false)}<details><summary>Quality flags, mapped columns and rejected rows</summary>${renderSourceInspection({...p,label:source.label,kind:source.kind,origin:source.origin||{}})}</details></div>`;}
  function recordTable(rows,inspect=true){if(!rows?.length)return '<p class="mw-empty">No measurements in this selection.</p>';return `<div class="mw-table-wrap"><table><thead><tr><th>Source date</th><th>Station</th><th>Constituent</th><th>Result</th><th>Fraction / basis</th><th>Review / eligibility</th>${inspect?'<th>Inspect</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.sampledDate||'—')}</td><td class="mw-mono">${esc(r.stationId||r.id)}</td><td>${esc(r.parameter||r.name||'Station')}</td><td class="mw-number">${esc(measurementValue(r))}</td><td>${esc(r.fraction||'—')} / ${esc(r.basis||'—')}</td><td>${r.eligible?(r.eligible.ok?'Usable measured input':esc(r.eligible.reasons.map(reasonText).join(' '))):esc((r.issues||[]).join(', ')||'No parse flags')}</td>${inspect?`<td><button data-record="${esc(r.id)}">Inspect</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
  async function loadRecords(){page=await api('/records?'+new URLSearchParams({...filters,offset,limit:50}));if(!dead)render();}
  function renderRecords(){area.innerHTML=`<section class="mw-panel"><div class="mw-panel-head"><h2>Measurements</h2><a class="mw-button" href="${base}/export.csv?${new URLSearchParams(filters)}" download>Export selection CSV</a></div><form id="mw-filter" class="mw-filters">${label('Station',`<select name="stationId">${option('','All stations')}${summary.stations.map(s=>option(s.id,s.id,filters.stationId)).join('')}</select>`)}${label('Constituent',`<select name="parameter">${option('','All constituents')}${[...new Set(summary.parameters.map(x=>x.parameter))].map(x=>option(x,x,filters.parameter)).join('')}</select>`)}${label('From',`<input type="date" name="from" value="${esc(filters.from||'')}">`)}${label('Through',`<input type="date" name="to" value="${esc(filters.to||'')}">`)}<button>Apply filters</button></form><p>${num(page?.total||0)} matching records. Censored values are bounds, never substituted point measurements.</p>${recordTable(page?.rows)}<div class="mw-buttons"><button data-action="previous"${offset===0?' disabled':''}>Previous</button><span>${num(offset+((page?.rows.length||0)?1:0))}–${num(offset+(page?.rows.length||0))} of ${num(page?.total||0)}</span><button data-action="next"${!page||offset+page.rows.length>=page.total?' disabled':''}>Next</button></div></section><section id="mw-inspector"></section>`;if(selected)renderInspector();}
  async function inspect(id){selected=await api('/records/'+encodeURIComponent(id));renderInspector();area.querySelector('#mw-inspector')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
  function renderInspector(){const box=area.querySelector('#mw-inspector');if(!box||!selected)return;const r=selected;box.innerHTML=`<section class="mw-panel"><div class="mw-panel-head"><h2>Measurement detail</h2><button data-action="close-detail">Close</button></div><dl><dt>Identity</dt><dd class="mw-mono">${esc(r.id)}</dd><dt>Reported</dt><dd>${esc(r.reportedValue)} ${esc(r.reportedUnit)} · ${esc(r.characteristic)}</dd><dt>Normalized</dt><dd>${num(r.value)} ${esc(r.unit)}; ${esc(r.censor)} censoring; lower ${num(r.lower)}, upper ${num(r.upper)}</dd><dt>Time support</dt><dd>${esc(r.sampledDate)} / ${esc(r.sampledAt||r.sourceTime||'date only')} / ${esc(r.timePrecision)} / ${esc(r.timeZone||'zone not supplied')}</dd><dt>Method / laboratory</dt><dd>${esc(r.method||'Unspecified')} / ${esc(r.laboratory||'Unspecified')}</dd><dt>Flags</dt><dd>${esc(r.issues.map(reasonText).join(' ')||'None')}</dd><dt>Native reach</dt><dd>${esc(r.mapping?.reachId||'Unassigned')}</dd><dt>Input eligibility</dt><dd>${esc(r.eligible.ok?'Usable measured input':r.eligible.reasons.map(reasonText).join(' '))}</dd></dl>${renderObservationContext(r)}<form id="mw-review"><div class="mw-two">${label('Review decision',`<select name="state">${['pending','include','exclude'].map(x=>option(x,x,r.review.state)).join('')}</select>`)}${label('Reviewer',`<input name="reviewer" required value="${esc(r.review.reviewer||'')}">`)}</div>${label('Rationale',`<textarea name="reason" required rows="2">${esc(r.review.reason||'')}</textarea>`)}${r.variantCount>1?'<label class="mw-check"><input type="checkbox" name="selectVersion"> Choose this included source revision; retain all alternatives.</label>':''}<button>Save review</button></form><details><summary>Source revisions (${r.variantCount})</summary><div class="mw-buttons">${r.variants.map(id=>`<button data-record="${esc(id)}"${id===r.id?' disabled':''}>${esc(id.slice(0,16))}${id===r.selectedVersion?' · selected':''}</button>`).join('')}</div></details><details><summary>Complete original row and provenance</summary><pre>${esc(JSON.stringify({raw:r.raw,sources:r.sources,detectionLimits:r.detectionLimits,characteristicInterpretation:r.characteristicInterpretation,detectionInterpretation:r.detectionInterpretation,history:r.history},null,2))}</pre></details></section>`;}
  function renderStations(){area.innerHTML=`<section class="mw-panel"><h2>Explicit station-to-reach assignments</h2><p>Choose reach identifiers supplied by the original Workspace. Coordinates and datum are shown for interpretation; proximity alone never assigns a station.</p>${!summary.reaches.length?'<p class="mw-notice">No native reaches are connected. Attach the original Workspace reach resolver to enable assignments.</p>':''}${!summary.stations.length?'<p class="mw-empty">Import chemistry or station metadata to begin.</p>':''}${summary.stations.map(s=>`<details class="mw-station"><summary><strong>${esc(s.id)}</strong> · ${esc(s.name)} <span>${num(s.recordCount)} records · ${esc(s.mapping?.reachId||'Unassigned')}</span></summary><p>Latitude ${num(s.latitude)}, longitude ${num(s.longitude)} · datum ${esc(s.datum||'not supplied')}</p><form data-station-form="${esc(s.id)}"><div class="mw-two">${label('Original native reach',`<select name="reachId">${option('','Unassigned',s.mapping?.reachId||'')}${summary.reaches.map(r=>option(r.id,r.name?`${r.id} · ${r.name}`:r.id,s.mapping?.reachId)).join('')}</select>`)}${label('Reviewer',`<input name="reviewer" required value="${esc(s.mapping?.reviewer||'')}">`)}</div>${label('Assignment rationale',`<textarea name="reason" rows="2" required>${esc(s.mapping?.reason||'')}</textarea>`)}<button>Save assignment</button></form></details>`).join('')}</section>`;}
  function renderExports(){area.innerHTML=`<div class="mw-grid"><section class="mw-panel"><h2>Reviewed measurement inputs</h2><p>Complete accepted and excluded populations, exact units and fractions, explicit reach IDs, source references, and exclusion reasons. Downstream calibration retains control of model and temporal matching.</p><p class="mw-notice">The native annual quantities PO4_KG, NH4_KG and NO3_KG require a scientific load derivation. They are not aliases for discrete concentrations.</p><div class="mw-buttons"><button data-action="calibration">Create input package</button><a class="mw-button" href="${base}/export.csv" download>All measurements CSV</a></div><div id="mw-export-result"></div></section><section class="mw-panel"><h2>Independently editable handover</h2><p>Export originals, canonical records, source-row provenance, station metadata, assignments, reviews, alternative revisions and saved exports. The receiver reparses originals and verifies canonical values before committing.</p><button data-action="portable">Export complete workspace</button><form id="mw-receive">${label('Complete workspace JSON','<input type="file" name="file" accept=".json" required>')}<p>Receiving creates data only in an empty measurement workspace. Existing work is retained.</p><button>Receive verified workspace</button></form></section></div><section class="mw-panel"><h2>Explicit concentration–discharge pairing</h2><p>Pairs a discrete total-nitrogen or total-phosphorus measurement with one approved daily mean discharge on the same source calendar date. Retains unpaired rows and ambiguity reasons.</p><form id="mw-loads"><div class="mw-two">${label('Chemistry station',`<select name="stationId" required>${stationOptions()}</select>`)}${label('Discharge station',`<select name="flowStationId" required>${stationOptions()}</select>`)}</div>${label('Constituent',`<select name="parameter">${option('tn','Total nitrogen, as N')}${option('tp','Total phosphorus, as P')}</select>`)}${label('Pairing rationale','<textarea name="rationale" required rows="2" placeholder="Why this discharge station and date support this sample"></textarea>')}<button>Create paired-load report</button></form><div id="mw-load-result"></div></section><section class="mw-panel"><h2>Reopen previous results</h2><p>Saved result snapshots preserve their original source revision, selected settings and full populations.</p><button data-tab="results">Open saved results</button></section>`;}
